import { expectTypeOf, it } from 'vitest';
import type {
  CompactionTarget,
  ItemCommand,
  MemoryStore,
  ReadContextInput,
} from '@print-an-agent/context-memory';

it('keeps add identities, per-read render overrides and target modes out of the public contract', () => {
  expectTypeOf<MemoryStore['commit']>().toBeFunction();
  const add: ItemCommand = { op: 'add', content: 'short' };
  // @ts-expect-error IDs for additions are generated by the domain.
  const badAdd: ItemCommand = { op: 'add', content: 'short', itemId: 'caller' };
  // @ts-expect-error Rendering is persisted document configuration.
  const badRead: ReadContextInput = { memoryId: 'a', render: { format: 'json' } };
  // @ts-expect-error Direct and calculated targets are mutually exclusive.
  const badTarget: CompactionTarget = { maxTokens: 1, ratio: 0.8 };
  void [add, badAdd, badRead, badTarget];
});
